"""Shared helpers for the local hook scripts (standard library only)."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
AGENT = ROOT / ".agent"


def read_input() -> dict:
    """Hook input arrives as JSON on stdin; an unreadable payload means no decision."""
    try:
        return json.load(sys.stdin)
    except (json.JSONDecodeError, ValueError):
        return {}


def deny(reason: str) -> None:
    """PreToolUse denial in the documented hookSpecificOutput shape."""
    print(json.dumps({"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": reason,
    }}))
    sys.exit(0)


def norm(path: str) -> str:
    return path.replace("\\", "/")

