"""Status line: write .agent/usage.json from the status-line JSON and print one short line."""
import json
import sys
import time
from pathlib import Path

USAGE = Path(__file__).resolve().parents[2] / ".agent" / "usage.json"


def dig(data: dict, *keys):
    for key in keys:
        if not isinstance(data, dict):
            return None
        data = data.get(key)
    return data


def main() -> None:
    try:
        data = json.load(sys.stdin)
    except (json.JSONDecodeError, ValueError):
        data = {}
    usage = {
        "five_hour_pct": dig(data, "rate_limits", "five_hour", "used_percentage"),
        "five_hour_resets_at": dig(data, "rate_limits", "five_hour", "resets_at"),
        "ctx_pct": dig(data, "context_window", "used_percentage"),
        "updated_at": int(time.time()),
    }
    try:
        USAGE.write_text(json.dumps(usage), encoding="utf-8")
    except OSError:
        pass
    ctx = "?" if usage["ctx_pct"] is None else f"{usage['ctx_pct']:.0f}%"
    five = "?" if usage["five_hour_pct"] is None else f"{usage['five_hour_pct']:.0f}%"
    print(f"ctx {ctx} | 5h {five}")


if __name__ == "__main__":
    main()

