"""PreToolUse (every tool): stop new work at 90% of the 5-hour limit, then halt once state is saved."""
import json
import re
import sys
import time
from datetime import datetime

from _common import AGENT, deny, norm, read_input

LIMIT = 90
STALE_SECONDS = 15 * 60
SAFE_GIT = re.compile(r"^\s*git\s+(status|diff|add|commit|log)\b")
READ_TOOLS = {"Read", "Glob", "Grep"}


def load_usage() -> dict | None:
    try:
        usage = json.loads((AGENT / "usage.json").read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if time.time() - usage.get("updated_at", 0) > STALE_SECONDS:
        return None  # a stale reading must not freeze the build
    return usage


def state_saved_after_crossing(usage: dict) -> bool:
    """STATE.md counts as saved once it was written after the threshold reading was taken."""
    try:
        mtime = (AGENT / "STATE.md").stat().st_mtime
    except OSError:
        return False
    marker = AGENT / "usage_stop_since"
    if not marker.exists():
        marker.write_text(str(time.time()), encoding="utf-8")
    since = float(marker.read_text(encoding="utf-8"))
    return mtime > since


def allowed_while_stopping(data: dict) -> bool:
    tool, inp = data.get("tool_name", ""), data.get("tool_input", {})
    if tool in READ_TOOLS:
        return True
    if tool in ("Write", "Edit"):
        return "/.agent/" in norm(str(inp.get("file_path", "")))
    if tool == "Bash":
        cmd = str(inp.get("command", ""))
        return bool(SAFE_GIT.match(cmd)) or ".agent/" in cmd and ">>" in cmd
    return False


def main() -> None:
    data = read_input()
    usage = load_usage()
    pct = usage.get("five_hour_pct") if usage else None
    if pct is None or pct < LIMIT:
        (AGENT / "usage_stop_since").unlink(missing_ok=True)
        return
    if state_saved_after_crossing(usage):
        resets = usage.get("five_hour_resets_at")
        when = datetime.fromtimestamp(resets).strftime("%H:%M") if resets else "the reset time"
        print(json.dumps({"continue": False, "stopReason":
            f"5-hour usage at {pct:.0f}%. State saved. Restart after {when}."}))
        sys.exit(0)
    if not allowed_while_stopping(data):
        deny(f"USAGE-STOP ({LIMIT}%): finish the stop procedure in .claude/CLAUDE.md section 9")


main()

